 <div class="g3">${FC.map(g=>`<div class="pan"><h3>${g.k}</h3>${g.rows.map(r=>`<div class="fc ${r[3]}"><b>${r[0]}</b><span>${r[1]}</span><em>${r[2]}</em></div>`).join('')}</div>`).join('')}</div>
