SC.roles=()=>{const A=[['Все объекты, пульт, прогноз',{OW:2,PM:1}],['Свой объект: объём работ, задачи, приоритеты',{OW:2,PM:2,SU:1,FR:1}],['Журналы и дневной отчёт',{OW:1,PM:2,SU:2,FR:2}],['Фото и разбор ИИ',{OW:1,PM:2,SU:2,FR:2}],['Люди и табель',{OW:1,PM:2,SU:2,FR:2,BH:1}],['Спецтехника',{OW:1,PM:2,SU:2}],['Заявки на материалы',{OW:2,PM:2,SU:2,FR:2,SN:2,BH:2}],['Деньги и акты',{OW:2,PM:1,BH:2}],['ИИ-ассистент',{OW:2,PM:2,SU:2}]];const R=Object.entries(ROLES);
 return `<div class="hd"><div><h2>Роли и права</h2><p>Шесть должностей с доступом, как вы назвали. Руководитель проекта видит только свой объект; основатель — все три. Подсобники и переменный состав в систему не входят.</p></div></div>
 <div class="tw"><table class="t mx"><thead><tr><th>Раздел</th>${R.map(([k,v])=>`<th class="c">${esc(v.av)}<span>${esc(k)}</span></th>`).join('')}</tr></thead><tbody>${A.map(a=>`<tr><td>${a[0]}</td>${R.map(([k,v])=>`<td class="c">${a[1][v.p]===2?'●':a[1][v.p]===1?'○':'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>
 <p class="mini">● — меняет · ○ — только смотрит · — — не видит. Права настраиваются без программиста.</p>
 <div class="g3">${R.map(([k,v])=>`<div class="pan"><h3>${esc(k)}</h3><p class="mini">${esc(v.n)} · ${esc(v.note)}</p></div>`).join('')}</div>`};

const TRG=[['Стадия объекта закрыта галочкой','Объект переходит на следующую стадию, чек-лист новой стадии — руководителю проекта и начальнику участка'],['Задаче поставлен приоритет «Срочно»','Уведомление бригадиру и начальнику участка; связанные заявки поднимаются наверх у снабженца и бухгалтера'],['Заявка на материал выше 10 млн ₸','Уходит на согласование основателю'],['Заявка оплачена','Снабженец и прораб получают дату доставки'],['Материал принят на площадке','Прорабу — запись во входной контроль'],['ИИ нашёл нарушение ТБ на фото','Уведомление инженеру по ТБ и начальнику участка, задача с фото'],['Материала осталось меньше чем на 7 дней','Предупреждение снабженцу и руководителю проекта'],['Задача просрочена','Исполнителю и руководителю проекта; в сводку основателю'],['Конец месяца','Черновик КС-2 из общего журнала — ПТО и бухгалтеру'],['19:00 каждый день','Сводка ИИ основателю: план/факт, люди, проблемы']];
SC.triggers=()=>`<div class="hd"><div><h2>Триггеры и согласования</h2><p>Система не работает сама за людей — она реагирует на события: поставили галочку, закрыли этап — объект или задача сами уходят нужным людям на рассмотрение.</p></div></div>
 <div class="tw"><table class="t"><thead><tr><th>№</th><th>Когда</th><th>Что происходит</th><th>Вкл.</th></tr></thead><tbody>${TRG.map((t,i)=>`<tr><td class="mono">${i+1}</td><td><b>${t[0]}</b></td><td>${t[1]}</td><td><span class="sw on" onclick="this.classList.toggle('on')"></span></td></tr>`).join('')}</tbody></table></div>
 <p class="mini">Правила добавляются и меняются на этапе шлифовки вместе с вами.</p>`;

SC.launch=()=>`<div class="hd"><div><h2>Запуск и стоимость</h2><p>Стандартный пакет разработки: своя система, один раз, без абонентской платы. Работает в браузере — с телефона и компьютера, без App Store и Play Market. Стоит на вашем сервере, все ключи — у вас.</p></div></div>
 <div class="pk1"><div><small>Стандартный пакет разработки</small><b>2 500 000 ₸</b><span>всё, что в демо, плюс пункты вашего ТЗ; запас 10–15 % часов на доработки при шлифовке</span></div><div><small>Срок</small><b>4–6 недель</b><span>первая выкатка — через 3 недели</span></div></div>
 <div class="pay3"><div><small>Старт · 10 %</small><b>250 000 ₸</b><span>предоплата, начинаем работу</span></div><div><small>Ядро · 45 %</small><b>1 125 000 ₸</b><span>после приёмки ядра</span></div><div><small>Сдача · 45 %</small><b>1 125 000 ₸</b><span>после шлифовки и передачи ключей</span></div></div>
 <div class="g2"><div class="pan"><h3>Ядро — первые 3 недели</h3>${['Объекты в проектном канбане, карточка объекта, стадии','Объём работ из проекта → задачи, приоритеты','Журналы, дневной отчёт прораба','Заявки на материалы с согласованием','Роли и права, вход с телефона'].map(x=>`<div class="li"><i>✓</i><span>${x}</span></div>`).join('')}</div>
 <div class="pan"><h3>Шлифовка — до сдачи</h3>${['ИИ: разбор журналов и печатные формы, фото, ассистент, прогноз','Люди, табель, спецтехника, материалы на объекте','Деньги по объектам, акты КС-2 / КС-3','Триггеры, сводка основателю','Ваши правки — «этап тысячи мелочей»'].map(x=>`<div class="li n"><i>→</i><span>${x}</span></div>`).join('')}</div></div>
 <div class="g2"><div class="pan"><h3>Ваши расходы потом</h3><div class="kv"><span>Сервер в облаке</span><b>≈ 10 000 ₸ в месяц</b></div><div class="kv"><span>ИИ-сервис</span><b>напрямую, по факту использования</b></div><div class="kv"><span>Поддержка</span><b>20 $ в час · копим, не выставляем за полчаса</b></div></div>
 <div class="pan"><h3>Следующий шаг</h3><p class="mini" style="font-size:12.4px">Вы присылаете техническое задание — сверяем с демо и включаем пункты, которые сегодня не проговорили. Показываете КП основателю, 10 % — и начинаем.</p></div></div>
 ${said('«По деньгам никаких проблем нет — самое главное, чтобы получилось».')}`;

