CARD.scopeai=()=>['Загрузка проекта','ИИ читает ведомость объёмов работ',`<div class="upl"><b>РП_ПС220_том3_ВОР.pdf</b><span>148 страниц · 6,4 МБ</span></div>${ai('ИИ нашёл',`<div class="kv"><span>Разделов</span><b>11</b></div><div class="kv"><span>Позиций объёма</span><b>214</b></div><div class="kv"><span>Не распознано — проверить вручную</span><b class="neg">3 строки</b></div><p class="mini">Строки с непонятными единицами помечены — руководитель проекта проверяет и подтверждает. Без подтверждения в задачи не уходят.</p>`)}<button class="bt p" onclick="closeM();toast('214 позиций добавлены в объём работ. 3 строки ждут проверки руководителя проекта.')">Подтвердить</button>`];
